}

architecture_body: /(?i)\barchitecture\s+(\w+)\s+of\s+(\w+)\s+is\b/ /(?i)\bbegin\b/ /(?i)\bend\b(?:\s+architecture\b)?(?:\s+\w+)?\s*;/
I {architecture_header_parts = []}
-> comment                              .push
-> dquote_string                        .push
-> space                                .push
-> subprogram_body                      .push
